/// <summary>
/// Extension of Table class SalesInvoiceHeaderFooterTmp
/// </summary>
[ExtensionOf(tableStr(SalesInvoiceHeaderFooterTmp))]
 final class AVASalesInvoiceHeaderFooterTmpDbt_Extension
{

}

Method.Source:
/// <summary>
/// insert record
/// </summary>
public void insert()
{
    next insert();

    //copy of the salesInvoicetmp from UsingExistingReportData()
    if(this.AVAOrigSalesInvoiceHeaderFooterTmp && this.AVAOrigSalesInvoiceHeaderFooterTmp != this.RecId)
    {
        //copy the markup
        AvaReportingMarkupTransTmp::copyMarkupTrans(this.TableId, this.AVAOrigSalesInvoiceHeaderFooterTmp, this.RecId);
        //reset the isCopy flag
        AvaReportingMarkupTransTmp::resetIsCopy(this.TableId, this.RecId, this.RecId);
    }
    else
    {
        //fill the markuptrans records
        CustInvoiceJour custInvoiceJour = CustInvoiceJour::findRecId(this.JournalRecId);
        if(custInvoiceJour)
        {
            boolean proforma = custInvoiceJour.isProforma();
            SalesTable salesTable = custInvoiceJour.salesTable();

            if(proforma)
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, salesTable, custInvoiceJour.LanguageId, proforma, custInvoiceJour.Qty, custInvoiceJour.SalesBalance, 0.0, salesTable.InclTax);
            }
            else
            {
                AvaReportingMarkupTransTmp::setMarkupTrans(this, custInvoiceJour, custInvoiceJour.LanguageId);
            }
        }
    }

    this.AVAOrigSalesInvoiceHeaderFooterTmp = this.RecId;
    this.doUpdate();

}

/// <summary>
/// deleterecord
/// </summary>
public void delete()
{
    AVAReportingMarkupTransTmp     trans;

    delete_from trans
        where trans.ReportDPTableId == this.TableId
        && trans.ReportDPRecId == this.RecId
        && trans.IsCopy == 0;

    next delete();
}
